// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

export function getLevelForXP(xp: number): Level {
  return LEVELS.find(l => xp >= l.minXp && xp < l.maxXp) || LEVELS[LEVELS.length - 1];
}

export function getChaptersByPart(part: number): Chapter[] {
  return CHAPTERS.filter(c => c.part === part);
}

export function getDevlogById(id: string): Devlog | undefined {
  return DEVLOGS.find(d => d.id === id);
}

export function getLexiconEntry(term: string): LexiconEntry | undefined {
  return LEXICON.find(e => e.tpsTerm.toLowerCase() === term.toLowerCase());
}
